const ic=(n,z)=>`<svg class="i"${z?` style="width:${z}px;height:${z}px"`:''}><use href="#i-${n}"/></svg>`;const $=s=>document.querySelector(s),p2=n=>String(n).padStart(2,'0');
const ld=t=>{const d=new Date(t);return d.getFullYear()+'-'+p2(d.getMonth()+1)+'-'+p2(d.getDate())};
const tm=t=>new Date(t).toTimeString().slice(0,5);
const fd=ms=>{const s=Math.round(ms/1000);return Math.floor(s/60)+'m '+p2(s%60)+'s'};
const uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,6);
const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const addD=(d,n)=>ld(new Date(d+'T12:00').getTime()+n*864e5);
const avg=a=>a.length?a.reduce((x,y)=>x+y,0)/a.length:0;
let db,D=[],view='today',cal=new Date(),tick,cur,TL=!!localStorage.tl,fq='',fcat='all';
const tx=(m,f)=>new Promise(r=>{const t=db.transaction('r',m),o=f(t.objectStore('r'));t.oncomplete=()=>r(o.result)});
const sv=async x=>{await tx('readwrite',s=>s.put(x));const i=D.findIndex(y=>y.id==x.id);i<0?D.push(x):D[i]=x};
const rm=async id=>{await tx('readwrite',s=>s.delete(id));D=D.filter(x=>x.id!=id)};
const nowFor=d=>d==ld(Date.now())?Date.now():new Date(d+'T12:00').getTime();
/* ---- data ---- */
const FARD=[['Fajr',2],['Dhuhr',4],['Asr',4],['Maghrib',3],['Isha',4]];
const PR=[...FARD.map(([n,r])=>({n,c:'Fard',r})),{n:'Sunnah before Fajr',c:'Sunnah',r:2},{n:'Sunnah before Dhuhr',c:'Sunnah',r:4},{n:'Sunnah after Dhuhr',c:'Sunnah',r:2},{n:'Sunnah after Maghrib',c:'Sunnah',r:2},{n:'Sunnah after Isha',c:'Sunnah',r:2},{n:'Witr',c:'Witr',r:3},{n:'Tahajjud',c:'Nafl',r:2},{n:'Duha (Chasht)',c:'Nafl',r:2},{n:'Ishraq',c:'Nafl',r:2}];
const prs=()=>[...PR,...D.filter(x=>x.type=='cp')];
const ST=['Qiyam & recitation','Ruku','Sajdah 1','Sitting between','Sajdah 2','Tashahhud/sitting'],K=['q','r','s1','j','s2','t'];
const seq=n=>{const a=[];for(let r=1;r<=n;r++){for(let s=0;s<5;s++)a.push([r,s]);if(r%2==0||r==n)a.push([r,5])}return a};
const SS='Sahih Muslim 595: 33 each of SubhanAllah, Alhamdulillah, Allahu Akbar after prayer.';
const L=[
{k:'subhan',t:'SubhanAllah',c:['after','general'],ar:'سُبْحَانَ اللَّهِ',tr:'SubhanAllah',en:'Glory be to Allah.',m:'Declares Allah free of every imperfection.',w:'After obligatory prayers; any time.',ctx:'Reported as part of the post-prayer tasbih. Extra repetitions beyond reported counts are a personal choice.',cn:'33 after prayer (reported)',df:33,ref:SS,au:'Sahih (Muslim)'},
{k:'hamd',t:'Alhamdulillah',c:['after','general'],ar:'الْحَمْدُ لِلَّهِ',tr:'Alhamdulillah',en:'All praise belongs to Allah.',m:'Praise and gratitude for Allah’s perfection and favours.',w:'After obligatory prayers; any time.',ctx:'Part of the post-prayer tasbih.',cn:'33 after prayer (reported)',df:33,ref:SS,au:'Sahih (Muslim)'},
{k:'akbar',t:'Allahu Akbar',c:['after','general'],ar:'اللَّهُ أَكْبَرُ',tr:'Allahu Akbar',en:'Allah is the Greatest.',m:'Allah is greater than anything we may be preoccupied with.',w:'After obligatory prayers; any time.',ctx:'Part of the post-prayer tasbih. Some reports mention 34 for this one; scholars note the variants.',cn:'33 after prayer (reported)',df:33,ref:SS,au:'Sahih (Muslim)'},
{k:'tahlil',t:'La ilaha illallah (completing phrase)',c:['after','general'],ar:'لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ',tr:'La ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamd, wa huwa ala kulli shay’in qadir.',en:'There is no god but Allah alone, no partner has He. His is the dominion and His is the praise, and He is over all things capable.',m:'Affirms Allah’s oneness and absolute authority.',w:'Once, after the 33-33-33 to complete one hundred.',ctx:'Reported as completing the hundred after the three 33s.',cn:'1 (reported)',df:1,ref:'Sahih Muslim 597.',au:'Sahih (Muslim)'},
{k:'astagh',t:'Astaghfirullah',c:['after','general'],ar:'أَسْتَغْفِرُ اللَّهَ',tr:'Astaghfirullah',en:'I seek forgiveness from Allah.',m:'A request for Allah’s pardon.',w:'Immediately after the salam of obligatory prayers; any time.',ctx:'Thawban reported the Prophet ﷺ sought forgiveness three times after finishing prayer.',cn:'3 after prayer (reported)',df:3,ref:'Sahih Muslim 591.',au:'Sahih (Muslim)'},
{k:'kursi',t:'Ayat al-Kursi',c:['after','morning','evening','quran'],ar:'اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ',tr:'Allahu la ilaha illa huwa al-Hayyul-Qayyum, la ta’khudhuhu sinatun wa la nawm, lahu ma fis-samawati wa ma fil-ard, man dhal-ladhi yashfa‘u ‘indahu illa bi-idhnih, ya‘lamu ma bayna aydihim wa ma khalfahum, wa la yuhituna bi-shay’in min ‘ilmihi illa bima sha’, wasi‘a kursiyyuhus-samawati wal-ard, wa la ya’uduhu hifzuhuma, wa huwal-‘Aliyyul-‘Azim.',en:'Allah: there is no god but Him, the Ever-Living, the Sustainer. Neither drowsiness nor sleep overtakes Him. To Him belongs whatever is in the heavens and the earth. Who can intercede with Him except by His permission? He knows what is before them and behind them, and they encompass nothing of His knowledge except what He wills. His Kursi extends over the heavens and the earth, and preserving them does not tire Him. He is the Most High, the Most Great.',m:'Describes Allah’s life, sustaining power, knowledge and authority.',w:'After obligatory prayers; morning/evening; before sleep.',ctx:'Reported with virtue after each prayer (an-Nasa’i, Sunan al-Kubra); also taught for protection at bedtime (Bukhari 2311).',cn:'1',df:1,ref:'Quran 2:255; an-Nasa’i Sunan al-Kubra (after prayer); Sahih al-Bukhari 2311 (bedtime). Verify numbering in your edition.',au:'Quran (certain). After-prayer report: graded sahih by al-Albani; scholars discuss the chain.'},
{k:'ikhlas',t:'Surah Al-Ikhlas',c:['after','morning','evening','quran'],ar:'قُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ ۝ لَمْ يَلِدْ وَلَمْ يُولَدْ ۝ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ',tr:'Qul huwa Allahu ahad. Allahus-samad. Lam yalid wa lam yulad. Wa lam yakun lahu kufuwan ahad.',en:'Say: He is Allah, One. Allah, the Eternal Refuge. He neither begets nor is born, nor is there anyone equal to Him.',m:'A concise statement of pure monotheism.',w:'After each prayer; 3 times morning and evening.',ctx:'The Prophet ﷺ taught reciting the three Quls after each prayer and three times morning/evening.',cn:'1 after prayer; 3 morning & evening (reported)',df:3,ref:'Abu Dawud 1523; Tirmidhi 2903 (after prayer); Abu Dawud 5082; Tirmidhi 3575 (morning/evening).',au:'Hasan (as graded by scholars such as al-Albani).'},
{k:'falaq',t:'Surah Al-Falaq',c:['after','morning','evening','quran'],ar:'قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ۝ مِنْ شَرِّ مَا خَلَقَ ۝ وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ ۝ وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ۝ وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ',tr:'Qul a‘udhu bi-rabbil-falaq. Min sharri ma khalaq. Wa min sharri ghasiqin idha waqab. Wa min sharrin-naffathati fil-‘uqad. Wa min sharri hasidin idha hasad.',en:'Say: I seek refuge in the Lord of daybreak, from the evil of what He created, from the evil of darkness when it settles, from the evil of those who blow on knots, and from the evil of an envier when he envies.',m:'Seeking Allah’s protection from harms.',w:'After each prayer; 3 times morning and evening.',ctx:'Same reports as Al-Ikhlas.',cn:'1 after prayer; 3 morning & evening (reported)',df:3,ref:'Abu Dawud 1523; Tirmidhi 2903; Abu Dawud 5082.',au:'Hasan (as graded by scholars such as al-Albani).'},
{k:'nas',t:'Surah An-Nas',c:['after','morning','evening','quran'],ar:'قُلْ أَعُوذُ بِرَبِّ النَّاسِ ۝ مَلِكِ النَّاسِ ۝ إِلَٰهِ النَّاسِ ۝ مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ۝ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ۝ مِنَ الْجِنَّةِ وَالنَّاسِ',tr:'Qul a‘udhu bi-rabbin-nas. Malikin-nas. Ilahin-nas. Min sharril-waswasil-khannas. Alladhi yuwaswisu fi sudurin-nas. Minal-jinnati wan-nas.',en:'Say: I seek refuge in the Lord of mankind, the Sovereign of mankind, the God of mankind, from the evil of the whispering withdrawer, who whispers in the hearts of mankind, from among jinn and mankind.',m:'Seeking refuge from whispers of evil.',w:'After each prayer; 3 times morning and evening.',ctx:'Same reports as Al-Ikhlas.',cn:'1 after prayer; 3 morning & evening (reported)',df:3,ref:'Abu Dawud 1523; Tirmidhi 2903; Abu Dawud 5082.',au:'Hasan (as graded by scholars such as al-Albani).'},
{k:'sayyid',t:'Sayyid al-Istighfar',c:['morning','evening','general'],ar:'اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَٰهَ إِلَّا أَنْتَ خَلَقْتَنِي وَأَنَا عَبْدُكَ وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ وَأَبُوءُ لَكَ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ',tr:'Allahumma anta rabbi la ilaha illa ant, khalaqtani wa ana ‘abduk, wa ana ‘ala ‘ahdika wa wa‘dika mastata‘t. A‘udhu bika min sharri ma sana‘t. Abu’u laka bi-ni‘matika ‘alayya, wa abu’u laka bi-dhanbi, faghfir li fa-innahu la yaghfirudh-dhunuba illa ant.',en:'O Allah, You are my Lord; none has the right to be worshipped but You. You created me and I am Your servant, and I keep Your covenant and promise as best I can. I seek refuge in You from the evil I have done. I acknowledge Your favour upon me and I acknowledge my sin, so forgive me, for none forgives sins but You.',m:'A comprehensive prayer of acknowledgement and repentance.',w:'Morning and evening.',ctx:'The Prophet ﷺ described it as the master of seeking forgiveness and mentioned its virtue when said with certainty.',cn:'1 (reported)',df:1,ref:'Sahih al-Bukhari 6306.',au:'Sahih (Bukhari)'},
{k:'durood',t:'Durood Ibrahim (Salawat)',c:['general'],ar:'اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ ۝ اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ',tr:'Allahumma salli ‘ala Muhammadin wa ‘ala ali Muhammad, kama sallayta ‘ala Ibrahima wa ‘ala ali Ibrahim, innaka Hamidun Majid. Allahumma barik ‘ala Muhammadin wa ‘ala ali Muhammad, kama barakta ‘ala Ibrahima wa ‘ala ali Ibrahim, innaka Hamidun Majid.',en:'O Allah, send prayers upon Muhammad and the family of Muhammad as You sent upon Ibrahim and his family; You are Praiseworthy, Glorious. O Allah, bless Muhammad and his family as You blessed Ibrahim and his family; You are Praiseworthy, Glorious.',m:'Asking Allah to honour and bless the Prophet ﷺ.',w:'In the final tashahhud of prayer; any time, especially Fridays.',ctx:'Taught by the Prophet ﷺ when Companions asked how to send salawat. Wording varies slightly between reports.',cn:'No fixed count; any number is a personal choice',df:10,ref:'Sahih al-Bukhari 3370; Sahih Muslim 406 (wording varies).',au:'Sahih'},
{k:'rabbana',t:'Rabbana atina (Quranic dua)',c:['quran','general'],ar:'رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ',tr:'Rabbana atina fid-dunya hasanatan wa fil-akhirati hasanatan wa qina ‘adhaban-nar.',en:'Our Lord, give us good in this world and good in the Hereafter, and protect us from the punishment of the Fire.',m:'A comprehensive dua for good in both lives.',w:'Any time; commonly between the Yemeni corner and the Black Stone in tawaf.',ctx:'Reported as one of the Prophet’s most frequent duas (Bukhari 6389).',cn:'No fixed count',df:0,ref:'Quran 2:201; Sahih al-Bukhari 6389.',au:'Quran (certain)'}];
const lib=()=>[...L,...D.filter(x=>x.type=='cd').map(x=>({k:x.id,t:x.n,c:['custom'],ar:x.ar,tr:x.tr,en:x.en,m:x.note,cn:'Your own target',df:x.target,ref:'Personal entry (not verified)',cu:1}))];
const title=k=>lib().find(x=>x.k==k)?.t||k;
const CATS=[['all','All'],['fav','Favorites'],['after','After Salah'],['morning','Morning'],['evening','Evening'],['general','General'],['quran','Quranic'],['custom','Custom']];
/* ---- UI helpers ---- */
const M=(t,b)=>{$('#m').innerHTML=t?`<div class="modal" onclick="if(event.target==this)cm()"><div class="win"><div class="tb">${esc(t)}<span><i onclick="cm()">x</i></span></div><div class="in">${b}</div></div></div>`:''};
const cm=()=>{M();render()};
const render=()=>{clearInterval(tick);$('#nav').innerHTML=[['today','Today','sun-horizon'],['salah','Salah','moon-stars'],['dhikr','Dhikr','circles-three'],['cal','Calendar','calendar-blank'],['stats','History','chart-line-up'],['set','Settings','gear-six']].map(([k,n,g])=>`<button class="${k==view?'on':''}" onclick="show('${k}')"><b>${ic(g)}</b>${n}</button>`).join('');$('#v').innerHTML=V[view]();if(view=='salah'){const a=D.find(x=>x.id=='act');if(a)tick=setInterval(()=>{const e=$('#tk');if(e){e.textContent=fd(Date.now()-(a.ev.at(-1)||a.start));$('#tt').textContent=fd(Date.now()-a.start)}},250)}if(view=='dhikr')dl()};
const show=v=>{view=v;render()};
const W=(t,b,cl='')=>`<div class="win ${cl}"><div class="tb">${t}<span><i>_</i><i>x</i></span></div>${b}</div>`;
const V={};
/* ---- day ---- */
const day=d=>{const S=D.filter(x=>x.type=='sess'&&x.date==d),H=D.filter(x=>x.type=='dh'&&x.date==d),N=D.filter(x=>x.type=='note'&&x.date==d);
const tt=S.reduce((a,x)=>a+x.end-x.start,0),rk=S.reduce((a,x)=>a+x.n,0),vol=S.filter(x=>x.cat!='Fard').length,rep=H.reduce((a,x)=>a+x.count,0);
const row=x=>`<div class="row" onclick="ds('${x.id}')">${tm(x.start)} <b>${esc(x.prayer)}</b> <small>${x.cat} · ${x.n} rak'ah · ${fd(x.end-x.start)}${x.st=='partial'?' · partial':''}</small></div>`;
const dr=x=>`<div class="row" onclick="dv('${x.id}')">${tm(x.t)} <b>${esc(title(x.key))}</b> <small>${x.count}${x.target?'/'+x.target:''} · ${x.st}${x.prayer?' · '+esc(x.prayer):''}</small></div>`;
const fc=n=>{const s=S.find(x=>x.prayer==n&&x.cat=='Fard'),m=D.find(x=>x.id=='m_'+d+n),a=H.filter(x=>x.prayer==n);
return `<div class="in"><b>${n}</b> ${s?`<span class="${'st-ok'}" onclick="ds('${s.id}')">${s.st=='partial'?ic('circle-half')+' partial':ic('check-circle')+' recorded'} · ${fd(s.end-s.start)}</span>`:m?`<span class="st-miss">${ic('x-circle')} marked missed</span> <button onclick="um('${m.id}')">undo</button>`:`<span class="mut">· not recorded</span> <button onclick="show('salah')">record</button> <button onclick="mm('${d}','${n}')">mark missed</button>`} <button class="y" onclick="asb('${d}','${n}')">after-salah${a.length?' ('+a.length+')':''}</button></div>`};
const list=(a,f,e)=>a.length?a.map(f).join(''):`<p class="mut">${e}</p>`;
const tl=[...S.map(x=>[x.start,row(x)]),...H.map(x=>[x.t,dr(x)])].sort((a,b)=>a[0]-b[0]).map(a=>a[1]).join('')||'<p class="mut">Nothing recorded for this date. Unrecorded ≠ missed.</p>';
return `<div class="grid">${W('Summary',`<div class="in">Prayer time: <b>${fd(tt)}</b><br>Rak'ahs recorded: <b>${rk}</b><br>Voluntary prayers: <b>${vol}</b><br>Dhikr repetitions: <b>${rep}</b></div>`)}${W('Fard',FARD.map(f=>fc(f[0])).join(''))}${W('Sunnah & Witr',`<div class="in">${list(S.filter(x=>x.cat=='Sunnah'||x.cat=='Witr'),row,'None recorded.')}</div>`)}${W('Nafl',`<div class="in">${list(S.filter(x=>x.cat=='Nafl'),row,'None recorded.')}</div>`)}${W('After-Salah Tasbihat',`<div class="in">${list(H.filter(x=>FARD.some(f=>f[0]==x.prayer)),dr,'None recorded.')}</div>`)}${W('Morning & Evening Adhkar',`<div class="in">${list(H.filter(x=>x.prayer=='morning'||x.prayer=='evening'),dr,'None recorded.')}</div>`)}${W('Other Dhikr',`<div class="in">${list(H.filter(x=>!FARD.some(f=>f[0]==x.prayer)&&x.prayer!='morning'&&x.prayer!='evening'),dr,'None recorded.')}</div>`)}${W('Other worship (Quran, notes)',`<div class="in">${list(N,x=>`<div class="row">${esc(x.text)} <button onclick="event.stopPropagation();dn('${x.id}')">x</button></div>`,'No notes.')}<input id="nt" placeholder="Quran read, dua, note…"> <button onclick="an('${d}')">add</button></div>`)}</div>${W('Timeline',`<div class="in">${tl}</div>`)}`};
V.today=()=>{const d=ld(Date.now());return W('Today · '+d,day(d))};
const mm=async(d,n)=>{await sv({id:'m_'+d+n,type:'miss',date:d,prayer:n});render()};
const um=async id=>{await rm(id);render()};
const an=async d=>{const v=$('#nt').value.trim();if(v){await sv({id:uid(),type:'note',date:d,text:v,t:nowFor(d)});M()||0;render()}};
const dn=async id=>{await rm(id);render()};
const od=d=>{M(d,`<button onclick="od('${addD(d,-1)}')">${ic('caret-left')} day</button> <button onclick="od('${addD(d,1)}')">day ${ic('caret-right')}</button> <button onclick="od('${addD(d,-7)}')">${ic('caret-double-left')} week</button> <button onclick="od('${addD(d,7)}')">week ${ic('caret-double-right')}</button>${day(d)}`)};
/* ---- after salah ---- */
const RT=['subhan','hamd','akbar','astagh','kursi'];
const asb=(d,n)=>{M('After '+n+' · '+d,`<p class="mut">Mark what you actually did. Default routine; edit counts freely.</p>${RT.map(k=>{const e=lib().find(x=>x.k==k),x=D.find(y=>y.id=='a_'+d+'_'+n+'_'+k);return `<div class="row" style="cursor:default"><b>${e.t}</b> <small>${e.cn}</small><br><input type="number" id="c_${k}" value="${x?x.count:e.df}"> <select id="s_${k}">${[['completed','Completed'],['partial','Partial'],['skipped','Skipped'],['nr','Not recorded']].map(([v,l])=>`<option value="${v}" ${(x?x.st:'nr')==v?'selected':''}>${l}</option>`).join('')}</select></div>`}).join('')}<button onclick="RT.forEach(k=>$('#s_'+k).value='completed')">all completed</button> <button class="y" onclick="asv('${d}','${n}')">save</button>`)};
const asv=async(d,n)=>{for(const k of RT){const id='a_'+d+'_'+n+'_'+k,st=$('#s_'+k).value,ex=D.find(x=>x.id==id);if(st=='nr'){if(ex)await rm(id)}else await sv({id,type:'dh',key:k,count:+$('#c_'+k).value||0,target:lib().find(x=>x.k==k).df,date:d,t:ex?.t||nowFor(d),ms:0,prayer:n,st})}cm()};
/* ---- salah ---- */
V.salah=()=>{const a=D.find(x=>x.id=='act'),P=prs();if(a)return actUI(a);const o=P.map((p,i)=>`<option value="${i}">${esc(p.n)} (${p.c}, ${p.r})</option>`).join('');
return W('Salah Timer.exe',`<div class="in"><b>Prayer</b> <select id="pr" onchange="$('#n').value=prs()[this.value].r">${o}</select> <b>Rak'ahs</b> <input type="number" id="n" min="1" max="40" value="2"><br><br><button class="y" onclick="startS()">Start detailed mode</button><p class="mut">Tap at the end of each position. Optional: use Quick log to enter details afterwards.</p></div><div class="in"><b>Quick log (simple/retrospective)</b><br><input type="date" id="qd" value="${ld(Date.now())}"> <input type="time" id="qt" value="${tm(Date.now())}"> <input type="number" id="qm" value="5" min="1"> min<br><br><button onclick="ql()">Save quick log</button> <span class="mut">Uses prayer + rak'ah count above. Add per-position times later by editing a detailed record.</span></div>`)};
setTimeout(()=>{},0);
const startS=async()=>{const p=prs()[$('#pr').value];await sv({id:'act',type:'act',id2:uid(),prayer:p.n,cat:p.c,n:Math.max(1,+$('#n').value||p.r),start:Date.now(),ev:[]});render()};
const ql=async()=>{const p=prs()[$('#pr').value],s=new Date($('#qd').value+'T'+$('#qt').value).getTime();if(isNaN(s))return alert('Invalid date/time');await sv({id:uid(),type:'sess',prayer:p.n,cat:p.c,date:ld(s),start:s,end:s+(+$('#qm').value||1)*6e4,mode:'simple',st:'completed',n:Math.max(1,+$('#n').value||p.r),rak:[],notes:''});show('today')};
const actUI=a=>{const sq=seq(a.n),i=a.ev.length,done=i>=sq.length,[r,s]=sq[i]||[a.n,5];
return W('Praying: '+esc(a.prayer),`<div class="in">${done?'<b>All positions recorded</b>':`<b>Rak'ah ${r} of ${a.n}</b><br>Now: <b>${ST[s]}</b>`}<div class="big" id="tk">0m 00s</div><small>Total <span id="tt">0m 00s</span> · step ${Math.min(i+1,sq.length)}/${sq.length}</small><div class="bar"><b style="width:${i/sq.length*100}%"></b></div>${done?'':`<button class="tap" onclick="nx()">End ${ST[s]}</button>`}<br><br><button onclick="udS()">Undo</button> <button onclick="dsS()">Discard</button> <button class="y" onclick="fnS()">Finish & save</button><br><br><textarea id="nt" rows="2" style="width:100%" placeholder="Notes: focus, distractions, calm…">${esc(a.notes||'')}</textarea></div><div class="in"><small>${a.ev.map((t,j)=>{const[rr,ss]=sq[j];return `R${rr} ${ST[ss]}: ${fd(t-(a.ev[j-1]||a.start))}`}).join('<br>')}</small></div>`)};
const nx=async()=>{const a=D.find(x=>x.id=='act');a.ev.push(Date.now());await sv(a);render()};
const udS=async()=>{const a=D.find(x=>x.id=='act');a.ev.pop();await sv(a);render()};
const dsS=async()=>{if(confirm('Discard this session?')){await rm('act');render()}};
const fnS=async()=>{const a=D.find(x=>x.id=='act'),sq=seq(a.n),part=a.ev.length<sq.length;if(part&&!confirm('Not all positions recorded. Save as partial?'))return;
const rak=[];let prev=a.start;a.ev.forEach((t,i)=>{const[r,s]=sq[i];(rak[r-1]=rak[r-1]||{})[K[s]]=t-prev;prev=t});for(let r=0;r<a.n;r++)rak[r]=rak[r]||{};
await sv({id:a.id2,type:'sess',prayer:a.prayer,cat:a.cat,date:ld(a.start),start:a.start,end:a.ev.length?a.ev.at(-1):Date.now(),mode:'detailed',st:part?'partial':'completed',n:a.n,rak,notes:$('#nt').value});await rm('act');show('today')};
/* session detail/edit */
const ds=id=>{const x=D.find(y=>y.id==id);if(!x)return;
const KK=x.mode=='pacer'?PK:K,SN=x.mode=='pacer'?PN:ST;const ed=x.rak.length?x.rak.map((r,i)=>`<div class="row" style="cursor:default"><b>Rak'ah ${i+1}</b><br>${KK.map((k,j)=>(k!='t'||r[k]!==undefined||i%2==1||i==x.n-1)?`<small>${SN[j]}</small> <input type="number" step="0.1" data-r="${i}" data-k="${k}" value="${r[k]!==undefined?(r[k]/1000).toFixed(1):''}" style="width:80px"> s<br>`:'').join('')}</div>`).join(''):`<p>Minutes <input type="number" id="em" value="${Math.round((x.end-x.start)/6e4)}"> Rak'ahs <input type="number" id="en" value="${x.n}"></p>`;
M(x.prayer+' · '+x.date,`<p><b>${x.cat}</b> · ${tm(x.start)}–${tm(x.end)} · ${fd(x.end-x.start)} · ${x.mode} · ${x.st}</p>${x.mode=='pacer'?`<p><small>Scheduled cue timings, not observed movements. Scheduled ${fd(x.sched)} · measured elapsed ${fd(x.actual)} · preset ${esc(x.preset)}</small></p>`:''}${ed}<textarea id="enn" rows="2" style="width:100%" placeholder="Notes">${esc(x.notes)}</textarea><br><button class="y" onclick="dsv('${id}')">save</button> <button onclick="ddel('${id}')">delete</button>`)};
const dsv=async id=>{const x=D.find(y=>y.id==id);x.notes=$('#enn').value;if(x.rak.length)document.querySelectorAll('[data-r]').forEach(e=>{if(e.value!=='')x.rak[+e.dataset.r][e.dataset.k]=Math.round(+e.value*1000);else delete x.rak[+e.dataset.r][e.dataset.k]});else{x.end=x.start+(+$('#em').value||1)*6e4;x.n=+$('#en').value||x.n}
if(x.mode=='detailed'){const t=x.rak.reduce((a,r)=>a+Object.values(r).reduce((b,c)=>b+c,0),0);x.end=x.start+t}await sv(x);cm()};
const ddel=async id=>{if(confirm('Delete this record permanently?')){await rm(id);cm()}};
/* dhikr record */
const dv=id=>{const x=D.find(y=>y.id==id);M(title(x.key),`<p>${x.date} ${tm(x.t)} · ${fd(x.ms)}${x.prayer?' · '+esc(x.prayer):''}</p>Count <input type="number" id="vc" value="${x.count}"> <select id="vs">${['completed','partial','skipped'].map(s=>`<option ${x.st==s?'selected':''}>${s}</option>`).join('')}</select><br><br><button class="y" onclick="dvs('${id}')">save</button> <button onclick="ddel('${id}')">delete</button>`)};
