/* ---- dhikr library + counter ---- */
V.dhikr=()=>W('Tasbihat & Adhkar',`<div class="in"><input id="fs" placeholder="Search…" value="${esc(fq)}" oninput="fq=this.value;dl()"> <select onchange="fcat=this.value;dl()">${CATS.map(([k,n])=>`<option value="${k}" ${fcat==k?'selected':''}>${n}</option>`).join('')}</select><p class="mut">Established counts come from reported sources; targets are your own choice. Add your own in Settings.</p></div><div id="dl"></div>`);
const dl=()=>{const e=$('#dl');if(!e)return;const q=fq.toLowerCase(),f=id=>D.some(x=>x.id=='fav_'+id);e.innerHTML=lib().filter(x=>(fcat=='all'||(fcat=='fav'?f(x.k):x.c.includes(fcat)))&&(x.t+x.tr+x.en).toLowerCase().includes(q)).map(x=>`<div class="in" style="cursor:pointer" onclick="dm('${x.k}')">${f(x.k)?ic('star-fill')+' ':''}<b>${esc(x.t)}</b> <small>· ${x.c.join(', ')} · ${esc(x.cn)}</small><div class="ar">${esc((x.ar||'').slice(0,90))}${(x.ar||'').length>90?'…':''}</div></div>`).join('')||'<p class="mut">No matches.</p>'};
const dm=k=>{const e=lib().find(x=>x.k==k);let c=D.find(x=>x.id=='cnt_'+k);if(!c)c={id:'cnt_'+k,type:'cnt',key:k,n:0,target:e.df||0,t0:0,t1:0,pre:'',paused:0};cur=c;const fv=D.some(x=>x.id=='fav_'+k);
M(e.t,`${e.ar?`<div class="ar">${esc(e.ar)}</div>`:''}<label><input type="checkbox" ${TL?'checked':''} onchange="TL=this.checked;localStorage.tl=TL?1:'';dm('${k}')"> transliteration</label>${TL&&e.tr?`<p><i>${esc(e.tr)}</i></p>`:''}<p><b>Meaning:</b> ${esc(e.en||'')}</p>${e.m?`<p>${esc(e.m)}</p>`:''}${e.w?`<p><b>When:</b> ${esc(e.w)}</p>`:''}${e.ctx?`<p><b>Context:</b> ${esc(e.ctx)}</p>`:''}<p><b>Established count:</b> ${esc(e.cn)}<br><b>Reference:</b> ${esc(e.ref)}<br><b>Authenticity:</b> ${esc(e.au||'Not verified')}</p><hr><div class="big">${c.n}${c.target?' / '+c.target:''}</div><button class="tap" onclick="tp()" ${c.paused?'disabled':''}>TAP</button><br><br><button onclick="un()">${ic('arrow-counter-clockwise')} Undo</button> <button onclick="pz()">${c.paused?'Resume':'Pause'}</button> <button onclick="rs()">Reset</button> <button onclick="fv('${k}')">${ic(fv?'star-fill':'star')} ${fv?'Unfavorite':'Favorite'}</button><br><br>Your target <input type="number" value="${c.target}" onchange="cur.target=+this.value;sv(cur);dm('${k}')"> Link to <select onchange="cur.pre=this.value;sv(cur)">${['','Fajr','Dhuhr','Asr','Maghrib','Isha','morning','evening'].map(v=>`<option value="${v}" ${c.pre==v?'selected':''}>${v||'none'}</option>`).join('')}</select><br><br><button class="y" onclick="fin()">Save session</button>`)};
const tp=async()=>{if(cur.paused)return;cur.n++;cur.t0=cur.t0||Date.now();cur.t1=Date.now();navigator.vibrate&&navigator.vibrate(15);await sv(cur);dm(cur.key)};
const un=async()=>{if(cur.n>0){cur.n--;await sv(cur)}dm(cur.key)};
const pz=async()=>{cur.paused=cur.paused?0:1;await sv(cur);dm(cur.key)};
const rs=async()=>{if(confirm('Reset counter to 0?')){cur.n=0;cur.t0=0;cur.t1=0;await sv(cur);dm(cur.key)}};
const fv=async k=>{D.some(x=>x.id=='fav_'+k)?await rm('fav_'+k):await sv({id:'fav_'+k,type:'fav',key:k});dm(k)};
const fin=async()=>{if(!cur.n)return alert('Nothing counted.');const t=cur.t0||Date.now();await sv({id:uid(),type:'dh',key:cur.key,count:cur.n,target:cur.target,date:ld(t),t,ms:cur.t1-cur.t0,prayer:cur.pre,st:cur.target&&cur.n<cur.target?'partial':'completed'});cur.n=0;cur.t0=0;cur.t1=0;await sv(cur);cm()};
/* ---- calendar ---- */
V.cal=()=>{const y=cal.getFullYear(),mo=cal.getMonth(),f=new Date(y,mo,1),dim=new Date(y,mo+1,0).getDate(),off=(f.getDay()+6)%7;
const mk=d=>{const S=D.filter(x=>x.type=='sess'&&x.date==d),H=D.some(x=>x.type=='dh'&&x.date==d||x.type=='note'&&x.date==d),M2=D.filter(x=>x.type=='miss'&&x.date==d),acc=new Set([...S.filter(s=>s.cat=='Fard').map(s=>s.prayer),...M2.map(m=>m.prayer)]).size;
return (S.length||H||M2.length?(acc>=5?`<span class="st-ok">${ic('check-circle')}</span>`:`<span class="st-par">${ic('circle-half')}</span>`):'')+(M2.length?`<span class="st-miss">${ic('x-circle')}</span>`:'')};
let c='';for(let i=0;i<off;i++)c+='<div class="h"></div>';for(let i=1;i<=dim;i++){const d=y+'-'+p2(mo+1)+'-'+p2(i);c+=`<div onclick="od('${d}')">${i}<br>${mk(d)}</div>`}
return W('Calendar · '+cal.toLocaleString('en',{month:'long',year:'numeric'}),`<div class="in"><button onclick="cm2(-12)">${ic('caret-double-left')}</button> <button onclick="cm2(-1)">${ic('caret-left')}</button> <button onclick="cm2(1)">${ic('caret-right')}</button> <button onclick="cm2(12)">${ic('caret-double-right')}</button> <input type="date" onchange="od(this.value)"><p><small>green check: all 5 Fard accounted · gold half: some records · rose x: marked missed · blank = nothing recorded (not proof of anything)</small></p><div class="cal">${['M','T','W','T','F','S','S'].map(x=>`<div class="h">${x}</div>`).join('')}${c}</div></div>`)};
const cm2=n=>{cal.setDate(1);cal.setMonth(cal.getMonth()+n);render()};
/* ---- stats ---- */
const bars=(rows,fmt)=>{const mx=Math.max(1,...rows.map(r=>r[1]));return rows.map(r=>`<div>${esc(r[0])} <small>${fmt(r[1])}</small><div class="bar"><b style="width:${r[1]/mx*100}%"></b></div></div>`).join('')||'<p class="mut">No data yet.</p>'};
V.stats=()=>{const S=D.filter(x=>x.type=='sess'),H=D.filter(x=>x.type=='dh'),Dt=S.filter(x=>x.mode=='detailed'),R=Dt.flatMap(x=>x.rak);
const a=k=>avg(R.map(r=>r[k]).filter(v=>v!==undefined));const byP={};S.forEach(x=>(byP[x.prayer]=byP[x.prayer]||[]).push(x.end-x.start));
const byC={};S.forEach(x=>byC[x.cat]=(byC[x.cat]||0)+1);const byK={};H.forEach(x=>byK[title(x.key)]=(byK[title(x.key)]||0)+x.count);
const fl=k=>avg(Dt.map(x=>x.rak[0]?.[k]).filter(v=>v!==undefined))/1000,ll=k=>avg(Dt.map(x=>x.rak.at(-1)?.[k]).filter(v=>v!==undefined))/1000;
const wk=d=>{const x=new Date(d+'T12:00');x.setDate(x.getDate()-(x.getDay()+6)%7);return ld(x)};const W1={};S.forEach(x=>(W1[wk(x.date)]=W1[wk(x.date)]||[0,0])[0]++);H.forEach(x=>(W1[wk(x.date)]=W1[wk(x.date)]||[0,0])[1]+=x.count);
const ks=Object.keys(W1).sort().slice(-8);
const g=v=>v.toFixed(1)+'s';
return W('History & Analytics',`<div class="in"><b>Position averages</b> <small>(${Dt.length} detailed sessions, ${R.length} rak'ahs)</small>${bars([['Qiyam',a('q')/1000],['Ruku',a('r')/1000],['Sajdah 1',a('s1')/1000],['Sitting between',a('j')/1000],['Sajdah 2',a('s2')/1000],['Tashahhud',a('t')/1000]].map(r=>[r[0],r[1]||0]),g)}<b>First vs last rak'ah</b> <small>Ruku ${g(fl('r')||0)} / ${g(ll('r')||0)} · Sajdah 1 ${g(fl('s1')||0)} / ${g(ll('s1')||0)}</small></div><div class="grid"><div class="in"><b>Avg total by prayer</b>${bars(Object.entries(byP).map(([k,v])=>[k,avg(v)/1000]),v=>fd(v*1000))}</div><div class="in"><b>Prayers by category</b>${bars(Object.entries(byC),v=>v)}</div><div class="in"><b>Dhikr repetitions</b>${bars(Object.entries(byK),v=>v)}</div><div class="in"><b>Weekly prayers recorded</b>${bars(ks.map(k=>[k,W1[k][0]]),v=>v)}<b>Weekly dhikr reps</b>${bars(ks.map(k=>[k,W1[k][1]]),v=>v)}</div></div><div class="in"><b>Search records</b><br><input id="fx" placeholder="name" oninput="fl2()"> <select id="fc" onchange="fl2()"><option value="">any category/status</option>${['Fard','Sunnah','Witr','Nafl','completed','partial','skipped','missed'].map(x=>`<option>${x}</option>`).join('')}</select> <input type="date" id="f1" onchange="fl2()"> <input type="date" id="f2" onchange="fl2()"> min rak'ah <input type="number" id="fr" value="0" oninput="fl2()"><div id="fr2"></div></div><p><small>Durations describe habits only; they say nothing about validity or acceptance.</small></p>`)};
const fl2=()=>{const q=$('#fx').value.toLowerCase(),c=$('#fc').value,a=$('#f1').value,b=$('#f2').value,mr=+$('#fr').value;const ok=d=>(!a||d>=a)&&(!b||d<=b);
const rows=[];D.forEach(x=>{if(x.type=='sess'&&ok(x.date)&&(!q||x.prayer.toLowerCase().includes(q))&&(!c||c==x.cat||c==x.st)&&x.n>=mr)rows.push([x.date,x.start,x.prayer,x.cat+' · '+x.n+" rak'ah · "+fd(x.end-x.start),`ds('${x.id}')`]);
if(x.type=='dh'&&ok(x.date)&&!mr&&(!q||title(x.key).toLowerCase().includes(q))&&(!c||c==x.st))rows.push([x.date,x.t,title(x.key),x.count+' · '+x.st,`dv('${x.id}')`]);
if(x.type=='miss'&&ok(x.date)&&!mr&&(!q||x.prayer.toLowerCase().includes(q))&&(!c||c=='missed'))rows.push([x.date,0,x.prayer,'marked missed',`od('${x.date}')`])});
rows.sort((p,q2)=>q2[0].localeCompare(p[0])||q2[1]-p[1]);$('#fr2').innerHTML=rows.length?`<table>${rows.slice(0,200).map(r=>`<tr onclick="${r[4]}" style="cursor:pointer"><td>${r[0]}</td><td>${esc(r[2])}</td><td>${esc(r[3])}</td></tr>`).join('')}</table>`:'<p class="mut">No matching records.</p>'};
/* ---- settings ---- */
V.set=()=>{const cp=D.filter(x=>x.type=='cp'),cd=D.filter(x=>x.type=='cd');
return W('Settings',`<div class="grid"><div class="in"><b>Add prayer type</b><br><input id="cn" placeholder="Name"> <select id="cc">${['Sunnah','Witr','Nafl'].map(x=>`<option>${x}</option>`).join('')}</select> <input type="number" id="cr" value="2" min="1"><br><br><button class="y" onclick="acp()">add</button>${cp.map(x=>`<div class="row" onclick="ddl('${x.id}')">${esc(x.n)} · ${x.c} · ${x.r} <small>(tap to delete)</small></div>`).join('')}</div><div class="in"><b>Add custom dhikr</b><br><input id="dn" placeholder="Name"><br><input id="da" placeholder="Arabic (optional)"><br><input id="dt" placeholder="Transliteration"><br><input id="de" placeholder="Meaning"><br><input type="number" id="dg" value="33"> target<br><br><button class="y" onclick="acd()">add</button>${cd.map(x=>`<div class="row" onclick="ddl('${x.id}')">${esc(x.n)} <small>(tap to delete)</small></div>`).join('')}</div><div class="in"><b>Backup</b><br><br><button onclick="ex()">Export JSON</button> <button onclick="csv('sess')">CSV sessions</button> <button onclick="csv('rak')">CSV rak'ahs</button> <button onclick="csv('dh')">CSV dhikr</button><br><br><input type="file" id="im" accept=".json"> <button onclick="imp()">Import JSON</button><p><small>Export regularly and keep the file safe. To restore: Import JSON; existing records are never overwritten, duplicates skipped.</small></p><button onclick="wipe()">Erase everything</button></div></div>`)};
const acp=async()=>{const n=$('#cn').value.trim();if(n){await sv({id:uid(),type:'cp',n,c:$('#cc').value,r:+$('#cr').value||2});render()}};
const acd=async()=>{const n=$('#dn').value.trim();if(n){await sv({id:'c_'+uid(),type:'cd',n,ar:$('#da').value,tr:$('#dt').value,en:$('#de').value,note:'',target:+$('#dg').value||0});render()}};
