const ex=()=>dl2('salah-journal-'+ld(Date.now())+'.json',JSON.stringify({app:'salah-journal',v:1,records:D.filter(x=>!['act','pact'].includes(x.type))},null,1),'application/json');
const csv=k=>{const q=v=>'"'+String(v??'').replace(/"/g,'""')+'"',S=D.filter(x=>x.type=='sess');let r;
if(k=='sess')r=[['id','date','prayer','category','start','end','duration_s','rakahs','mode','status','notes'],...S.map(x=>[x.id,x.date,x.prayer,x.cat,new Date(x.start).toISOString(),new Date(x.end).toISOString(),(x.end-x.start)/1000,x.n,x.mode,x.st,x.notes])];
else if(k=='rak')r=[['session_id','rakah','qiyam_s','ruku_s','sajdah1_s','sitting_s','sajdah2_s','tashahhud_s'],...S.flatMap(x=>x.rak.map((a,i)=>[x.id,i+1,...K.map(z=>a[z]===undefined?'':a[z]/1000)]))];
else r=[['id','date','dhikr','count','target','duration_s','linked','status'],...D.filter(x=>x.type=='dh').map(x=>[x.id,x.date,title(x.key),x.count,x.target,x.ms/1000,x.prayer,x.st])];
dl2(k+'.csv',r.map(a=>a.map(q).join(',')).join('\n'),'text/csv')};
const imp=async()=>{const f=$('#im').files[0];if(!f)return alert('Choose a file');try{const j=JSON.parse(await f.text());if(j.app!='salah-journal'||!Array.isArray(j.records))throw 'Not a Salah Journal backup';const T=['sess','dh','miss','cp','cd','note','fav','cnt','pp','snd'];j.records.forEach(x=>{if(!x||typeof x.id!='string'||!T.includes(x.type))throw 'Invalid record: '+JSON.stringify(x).slice(0,80);if(x.type=='sess'&&(typeof x.start!='number'||typeof x.end!='number'||!Array.isArray(x.rak)))throw 'Invalid session '+x.id});
const nw=j.records.filter(x=>!D.some(y=>y.id==x.id));if(!confirm(nw.length+' new records ('+(j.records.length-nw.length)+' duplicates skipped). Import?'))return;for(const x of nw)await sv(x);alert('Imported '+nw.length);render()}catch(e){alert('Import failed, nothing changed: '+e)}};
const wipe=async()=>{if(confirm('Erase ALL records? Export first.')&&confirm('Really erase everything? This cannot be undone.')){for(const x of [...D])await rm(x.id);render()}};
/* ---- boot ---- */
(async()=>{db=await new Promise((r,j)=>{const q=indexedDB.open('salahj',1);q.onupgradeneeded=()=>q.result.createObjectStore('r',{keyPath:'id'});q.onsuccess=()=>r(q.result);q.onerror=j});D=await tx('readonly',s=>s.getAll());render();chkPact();loadOwn();if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('sw.js')})();
/* ===== AUTOMATIC SALAH PACER ===== */
const PK=['q','r','qa','s1','j','s2','t'],PN=['Qiyam & recitation','Ruku','Standing after Ruku','Sajdah 1','Sitting between Sajdahs','Sajdah 2','Tashahhud / sitting'],SH=['Stand','Ruku','Rise','Sajdah','Sit','Sajdah','Tashahhud'],PW=[6,2,1,3,1,3,3],PF=[440,587,523,659,494,740,392],SR=11025;
const hasT=(i,n)=>i%2==1||i==n-1,cl=o=>JSON.parse(JSON.stringify(o));
const gen=(min,n)=>{let W=0;for(let i=0;i<n;i++)PW.forEach((w,j)=>{if(PK[j]!='t'||hasT(i,n))W+=w});const u=min*60/W;return Array.from({length:n},(_,i)=>Object.fromEntries(PK.map((k,j)=>[k,{on:k!='t'||hasT(i,n)?1:0,d:Math.max(1,Math.round(PW[j]*u))}])))};
let PZ;try{PZ=JSON.parse(localStorage.pz)}catch(e){}if(!PZ||!PZ.rak)PZ={pi:0,n:2,min:5,lead:5,rak:gen(5,2),snd:{},rs:1,es:1,name:'5 min'};
let GS;try{GS=JSON.parse(localStorage.gs)}catch(e){}if(!GS)GS={vol:.7,silent:0,st:'bell'};
const savePZ=()=>localStorage.pz=JSON.stringify(PZ),saveGS=()=>localStorage.gs=JSON.stringify(GS);
const fix=()=>{while(PZ.rak.length<PZ.n){const l=cl(PZ.rak.at(-1));l.t.on=hasT(PZ.rak.length,PZ.n)?1:0;PZ.rak.push(l)}};
const steps=c=>{const s=[];let t=c.lead;c.rak.slice(0,c.n).forEach((r,i)=>PK.forEach(k=>{if(r[k]&&r[k].on&&r[k].d>0){s.push({i,k,d:r[k].d,t0:t});t+=r[k].d}}));return{s,total:t}};
/* audio: whole session rendered into ONE wav and played as a media track (keeps running with screen locked on most devices) */
const tone=(b,at,f,dur,a,k,ak=.008)=>{const s0=Math.floor(at*SR),n=Math.floor(dur*SR);for(let i=0;i<n&&s0+i<b.length;i++){const t=i/SR,e=Math.min(1,t/ak)*Math.exp(-t*k);b[s0+i]+=a*e*(Math.sin(6.2832*f*t)+.25*Math.sin(12.5664*f*t)*Math.exp(-t*8))}};
const SND=[['bell','Temple bell'],['bowl','Singing bowl'],['chime','Soft chime'],['drop','Water drop'],['pad','Gentle pad'],['tick','Wood tick']];let CS=null;
const voice=(b,at,f,a)=>{const st=GS.st||'bell';if(st=='own'&&CS){const s0=Math.floor(at*SR);for(let i=0;i<CS.length&&s0+i<b.length;i++)b[s0+i]+=CS[i]*a*1.6;return}
if(st=='bowl'){tone(b,at,f/2,2.4,.6*a,2);tone(b,at,f*1.5,1.6,.15*a,3.2)}
else if(st=='chime'){tone(b,at,f*2,.7,.35*a,8);tone(b,at,f*3,.4,.12*a,14)}
else if(st=='drop'){const s0=Math.floor(at*SR),n=Math.floor(.35*SR);let ph=0;for(let i=0;i<n&&s0+i<b.length;i++){const t=i/SR;ph+=6.2832*f*(1+1.2*Math.exp(-t*22))/SR;b[s0+i]+=.55*a*Math.sin(ph)*Math.min(1,t/.003)*Math.exp(-t*11)}}
else if(st=='pad'){tone(b,at,f,1.8,.45*a,2.6,.12);tone(b,at,f*1.5,1.8,.15*a,2.6,.12)}
else if(st=='tick'){const s0=Math.floor(at*SR),n=Math.floor(.09*SR);for(let i=0;i<n&&s0+i<b.length;i++){const t=i/SR;b[s0+i]+=a*.7*Math.exp(-t*60)*(Math.sin(6.2832*900*t)*.7+(Math.random()-.5)*.6)}}
else tone(b,at,f,.6,.5*a,7)};
const cue=(b,at,type,f,v)=>{const gap=GS.st=='own'&&CS?CS.length/SR+.15:GS.st=='bowl'?.9:.28;if(type=='stage')voice(b,at,f||587,v);else if(type=='rak'){voice(b,at,523,v);voice(b,at+gap,784,v)}else[523,659,784].forEach((x,j)=>voice(b,at+j*(gap+.1),x,v*.8))};
const loadOwn=async()=>{const r=D.find(x=>x.id=='snd');if(!r){CS=null;return}try{const ab=await(await fetch(r.data)).arrayBuffer(),ac=new(window.AudioContext||window.webkitAudioContext)(),dec=await ac.decodeAudioData(ab);try{ac.close()}catch(e){}const len=Math.min(dec.duration,6),oc=new OfflineAudioContext(1,Math.ceil(len*SR),SR),sr=oc.createBufferSource();sr.buffer=dec;sr.connect(oc.destination);sr.start();let o=(await oc.startRendering()).getChannelData(0).slice(),m=0;o.forEach(x=>m=Math.max(m,Math.abs(x)));CS=m>0?o.map(x=>x/m*.7):o}catch(e){CS=null}};
const upSnd=async inp=>{const f=inp.files[0];if(!f)return;if(f.size>1.5e6)return alert('File too large (max 1.5 MB).');const data=await new Promise(r=>{const fr=new FileReader();fr.onload=()=>r(fr.result);fr.readAsDataURL(f)});await sv({id:'snd',type:'snd',name:f.name,data});await loadOwn();if(!CS)return alert('Could not read this audio file.');GS.st='own';saveGS();pv('stage',587);pss()};
const wavBlob=(f,sr)=>{const n=f.length,B=new ArrayBuffer(44+n*2),v=new DataView(B),w=(o,s)=>[...s].forEach((c,i)=>v.setUint8(o+i,c.charCodeAt(0)));w(0,'RIFF');v.setUint32(4,36+n*2,1);w(8,'WAVEfmt ');v.setUint32(16,16,1);v.setUint16(20,1,1);v.setUint16(22,1,1);v.setUint32(24,sr,1);v.setUint32(28,sr*2,1);v.setUint16(32,2,1);v.setUint16(34,16,1);w(36,'data');v.setUint32(40,n*2,1);for(let i=0;i<n;i++)v.setInt16(44+i*2,Math.max(-1,Math.min(1,f[i]))*32767,1);return new Blob([B],{type:'audio/wav'})};
const synth=(c,s,total)=>{const b=new Float32Array(Math.ceil((total+2.5)*SR)),v=GS.silent?0:GS.vol,cues=[];s.forEach((x,j)=>{const nr=j>0&&s[j-1].i!=x.i;if(nr&&c.rs)cues.push([x.t0,'rak',0]);else if(c.snd[x.k]!==0&&GS.cm!=='rak')cues.push([x.t0,'stage',PF[PK.indexOf(x.k)]])});if(c.es)cues.push([total,'end',0]);cues.forEach(q=>cue(b,q[0],q[1],q[2],v));return{b,cues}};
const pv=(type,f)=>{const b=new Float32Array(SR*2.5);cue(b,.05,type,f,GS.silent?0:GS.vol);new Audio(URL.createObjectURL(wavBlob(b,SR))).play().catch(()=>{})};
/* runner */
let AU,PR2,PT,PS,WL;
let PZB=0;const pzKill=()=>{clearInterval(PT);clearInterval(PS);try{if(AU){AU.pause();AU.removeAttribute&&AU.removeAttribute('src');AU.load&&AU.load()}}catch(e){}};
const pzStart=async()=>{if(PZB||(PR2&&!PR2.done))return;PZB=1;try{await pzStart0()}finally{PZB=0}};
const pzStart0=async()=>{pzKill();fix();const c=cl(PZ),{s,total}=steps(c),p=prs()[c.pi];if(!s.length)return alert('Enable at least one stage.');const{b}=synth(c,s,total);AU=new Audio();AU.src=URL.createObjectURL(wavBlob(b,SR));try{await AU.play()}catch(e){return alert('Audio blocked by browser: '+e)}
PR2={c,s,total,p,start:Date.now(),pa:0,pat:0,done:0};try{WL=await navigator.wakeLock.request('screen')}catch(e){}
if('mediaSession'in navigator){try{navigator.mediaSession.metadata=new MediaMetadata({title:'Salah · '+p.n,artist:'Salah Journal'});navigator.mediaSession.setActionHandler('play',pzPause);navigator.mediaSession.setActionHandler('pause',pzPause);navigator.mediaSession.setActionHandler('stop',pzStop)}catch(e){}}
sv({id:'pact',type:'pact',start:PR2.start,lead:c.lead,prayer:p.n,seen:Date.now()});pzUI();PT=setInterval(pzTick,250);PS=setInterval(()=>sv({id:'pact',type:'pact',start:PR2.start,lead:c.lead,prayer:p.n,seen:Date.now(),at:AU.currentTime}),5000)};
const pzUI=()=>{const o=$('#pz');o.style.display='flex';o.innerHTML=`<span class="chip">${esc(PR2.p.n)}</span><div class="mut" id="pzr"></div><h2 id="pzs"></h2><div class="ringw"><svg viewBox="0 0 120 120"><circle cx="60" cy="60" r="54" class="rb"/><circle id="rg" cx="60" cy="60" r="54" class="rf"/></svg><div id="pzt"></div></div><div class="mut" id="pzd"></div><div class="bar" style="width:min(80%,360px)"><b id="pzb" style="width:0"></b></div><div class="ctl"><button id="pzp" onclick="pzPause()">${ic('pause')} Pause</button><button onclick="pzStop()">${ic('stop')} Stop</button></div><small class="mut">No taps needed. Cues play automatically.</small>`};
const pzTick=()=>{const x=PR2;if(!x||x.done)return;const t=AU.currentTime;if(t>=x.total-.05||AU.ended)return pzFinish(0);let st=null;x.s.forEach(q=>{if(q.t0<=t)st=q});const set=(i,v)=>{const e=document.getElementById(i);if(e)e.textContent=v};let rem,dur;
if(!st){rem=x.c.lead-t;dur=x.c.lead;set('pzr','Get ready');set('pzs','Begin shortly')}else{rem=st.t0+st.d-t;dur=st.d;set('pzr',`Rak'ah ${st.i+1} of ${x.c.n}`);set('pzs',PN[PK.indexOf(st.k)])}
set('pzt',Math.max(0,Math.ceil(rem)));set('pzd','of '+dur+'s'+(AU.paused?' · paused':''));const g=document.getElementById('rg');if(g)g.style.strokeDashoffset=339.3*(1-Math.max(0,Math.min(1,rem/dur)));const b=document.getElementById('pzb');if(b)b.style.width=Math.min(100,t/x.total*100)+'%'};
const pzPause=()=>{const x=PR2;if(!x||x.done)return;if(AU.paused){x.pa+=Date.now()-x.pat;AU.play()}else{x.pat=Date.now();AU.pause()}const e=$('#pzp');if(e)e.innerHTML=AU.paused?ic('play')+' Resume':ic('pause')+' Pause'};
const pzStop=()=>{if(!PR2||PR2.done)return;if(confirm('Stop now and save as interrupted?'))pzFinish(1)};
const pzFinish=async intr=>{const x=PR2;if(!x||x.done)return;x.done=1;clearInterval(PT);clearInterval(PS);const now=Date.now(),tp=intr?AU.currentTime:Infinity,aT=Math.min(AU.currentTime,x.total);const u=AU.src;pzKill();URL.revokeObjectURL(u);try{WL&&WL.release()}catch(e){}
let act=intr?aT*1000:now-x.start-x.pa;if(!intr&&Math.abs(act-x.total*1000)>4000)act=x.total*1000;const L=x.c.lead*1000;act=Math.round(act-L);const rak=[];
x.s.forEach(q=>{if(q.t0<=tp){(rak[q.i]=rak[q.i]||{})[q.k]=Math.round(Math.min(q.d,tp-q.t0)*1000)}});const n=intr?rak.length:x.c.n;for(let i=0;i<n;i++)rak[i]=rak[i]||{};
$('#pz').style.display='none';await rm('pact');if(act<=0||!n){show('salah');return}const id=uid(),ps=x.start+L;
await sv({id,type:'sess',prayer:x.p.n,cat:x.p.c,date:ld(ps),start:ps,end:ps+act,mode:'pacer',st:intr?'partial':'completed',n,rak,notes:intr?'Stopped early':'',sched:Math.round((x.total-x.c.lead)*1000),actual:act,preset:x.c.name||'custom'});if(!intr&&x.p.c=='Fard'&&GS.at!==0)tgStart(x.p.n,ld(ps));else{show('today');ds(id)}};
const chkPact=()=>{const a=D.find(x=>x.id=='pact');if(!a)return;const L=a.lead*1000,act=Math.round((a.seen-a.start)-L);if(act>0&&confirm('An interrupted pacer session was found ('+a.prayer+'). Save it as interrupted?')){const p=prs().find(x=>x.n==a.prayer)||{c:'Nafl'},ps=a.start+L;sv({id:uid(),type:'sess',prayer:a.prayer,cat:p.c,date:ld(ps),start:ps,end:ps+act,mode:'simple',st:'partial',n:1,rak:[],notes:'Interrupted pacer session (app closed). Timing approximate.'}).then(()=>rm('pact')).then(render)}else rm('pact')};
