const setP=i=>{PZ.pi=+i;const p=prs()[PZ.pi];PZ.n=p.r;if(PZ.min)PZ.rak=gen(PZ.min,PZ.n);else{PZ.rak=PZ.rak.slice(0,PZ.n);fix()}savePZ();render()};
